-- Contrato propuesto para acordar con Renzo. No inserta datos.
CREATE TABLE IF NOT EXISTS pedido_t(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(40) NOT NULL UNIQUE,cliente_id BIGINT,dni VARCHAR(8) NOT NULL,nombre VARCHAR(120) NOT NULL,correo VARCHAR(160),telefono VARCHAR(9),direccion VARCHAR(250),entrega VARCHAR(30) NOT NULL,metodo VARCHAR(30) NOT NULL,estado VARCHAR(30) NOT NULL,total DECIMAL(12,2) NOT NULL,descuento DECIMAL(12,2) NOT NULL,cupon VARCHAR(40),creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP,clave VARCHAR(80) NOT NULL UNIQUE);

CREATE TABLE IF NOT EXISTS detalle_t(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,pedido_id BIGINT NOT NULL REFERENCES pedido_t(id),producto_id BIGINT NOT NULL,nombre VARCHAR(120) NOT NULL,cantidad INT NOT NULL CHECK(cantidad>0),precio DECIMAL(12,2) NOT NULL);

CREATE TABLE IF NOT EXISTS pago_t(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,pedido_id BIGINT NOT NULL REFERENCES pedido_t(id),monto DECIMAL(12,2) NOT NULL CHECK(monto>0),metodo VARCHAR(30) NOT NULL,referencia VARCHAR(100) NOT NULL UNIQUE,estado VARCHAR(20) NOT NULL,creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS seguimiento_t(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,pedido_id BIGINT NOT NULL REFERENCES pedido_t(id),estado VARCHAR(30) NOT NULL,nota VARCHAR(500) NOT NULL,creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
